    ema50_1h = ind.ema(hist.htf(60).close, 50)
    ema50_1h_val = float(ema50_1h[-1]) if len(ema50_1h) else float("nan")

    # Donchian breakout on completed prior 20 bars, excluding current bar
    if len(hist) >= 21:
        prev20_high = float(np.max(high[-21:-1]))
        prev20_low = float(np.min(low[-21:-1]))
    else:
        prev20_high = float("nan")
        prev20_low = float("nan")

    c = float(close[-1])
    long_sig = (not math.isnan(prev20_high)) and c > prev20_high and (not math.isnan(ema50_1h_val)) and c > ema50_1h_val
    short_sig = (not math.isnan(prev20_low)) and c < prev20_low and (not math.isnan(ema50_1h_val)) and c < ema50_1h_val

    # State bookkeeping
    entry_price = state.get("entry_price", 0.0)
    entry_atr = state.get("entry_atr", 0.0)
    entry_bar = int(state.get("entry_bar", -1))
    half_taken = bool(state.get("half_taken", False))
    side = int(state.get("side", 0))  # 1 long, -1 short, 0 flat
    extreme = state.get("extreme", 0.0)

    # If flat, react to signals
    if pos == 0.0:
        # Clear trade state when flat
        if "side" in state:
            del state["side"]
        if "entry_price" in state:
            del state["entry_price"]
        if "entry_atr" in state:
            del state["entry_atr"]
        if "entry_bar" in state:
            del state["entry_bar"]
        if "half_taken" in state:
            del state["half_taken"]
        if "extreme" in state:
            del state["extreme"]

        if long_sig and not short_sig:
            state["side"] = 1
            state["entry_price"] = c
            state["entry_atr"] = atr
            state["entry_bar"] = t
            state["half_taken"] = False
            state["extreme"] = float(high[-1])
            return {"target": 0.25, "stop": None, "take": None}
        if short_sig and not long_sig:
            state["side"] = -1
            state["entry_price"] = c
            state["entry_atr"] = atr
            state["entry_bar"] = t
            state["half_taken"] = False
            state["extreme"] = float(low[-1])
            return {"target": -0.25, "stop": None, "take": None}
        return {"target": 0.0, "stop": None, "take": None}

    # If position exists, infer side if missing
    if side == 0:
        side = 1 if pos > 0 else -1
        state["side"] = side

    # Opposite signal closes immediately at next open
    if side > 0 and short_sig:
        return {"target": 0.0, "stop": None, "take": None}
    if side < 0 and long_sig:
        return {"target": 0.0, "stop": None, "take": None}

    # Update tracked extreme based on current bar
    if side > 0:
        extreme = max(float(extreme), float(high[-1])) if extreme != 0.0 else float(high[-1])
        state["extreme"] = extreme
    else:
        extreme = min(float(extreme), float(low[-1])) if extreme != 0.0 else float(low[-1])
        state["extreme"] = extreme

    # Time stop: exit at the open after 32 bars
    if entry_bar >= 0 and (t - entry_bar) >= 32:
        return {"target": 0.0, "stop": None, "take": None}

    # Scale out once when close is 2 ATR in profit
    target = pos
    if (not half_taken) and entry_atr > 0.0:
        if side > 0 and c >= entry_price + 2.0 * entry_atr:
            target = 0.125
            state["half_taken"] = True
        elif side < 0 and c <= entry_price - 2.0 * entry_atr:
            target = -0.125
            state["half_taken"] = True

    # Trailing stop 3 ATR behind extreme
    stop = None
    if entry_atr > 0.0:
        if side > 0:
            stop = float(extreme - 3.0 * entry_atr)
        else:
            stop = float(extreme + 3.0 * entry_atr)

    return {"target": float(target), "stop": stop, "take": None}

